class Gradebook:
    def __init__(self) -> None:
        self.assignment_weights = {}  # name -> weight
        self.assignment_kinds = {}    # name -> kind
        self.grades = {}              # student -> {assignment: grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError("kind must be 'homework' or 'quiz'")
        self.assignment_weights[name] = weight
        self.assignment_kinds[name] = kind

    def record(self, student: str, assignment: str, grade: float) -> None:
        if grade < 2.0 or grade > 5.0:
            raise ValueError("grade must be between 2.0 and 5.0")
        if assignment not in self.assignment_weights:
            raise KeyError("unknown assignment")
        self.grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        # Determine effective weight per assignment for this student.
        student_grades = self.grades.get(student, {})

        # Collect quiz assignments this student has recorded.
        quizzes = [
            a for a in self.assignment_weights
            if self.assignment_kinds.get(a) == "quiz" and a in student_grades
        ]

        dropped = None
        if len(quizzes) > 1:
            dropped = min(quizzes, key=lambda a: student_grades[a])

        total_weight = 0.0
        weighted_sum = 0.0

        for name, weight in self.assignment_weights.items():
            if name == dropped:
                continue
            grade = student_grades.get(name, 2.0)
            weighted_sum += weight * grade
            total_weight += weight

        if total_weight == 0:
            return 0.0
        return weighted_sum / total_weight
